backup_export_command:
node --import tsx -e "
import { writeFileSync, mkdirSync } from 'node:fs';
import path from 'node:path';
import { getSupabaseServerClient } from './src/lib/supabase/server-client.ts';
const slug = 'holmes-hapf30';
const supabase = getSupabaseServerClient();
const { data: filter, error: fErr } = await supabase.from('air_purifier_filters').select('id, slug').ilike('slug', slug).maybeSingle();
if (fErr) throw fErr;
if (!filter) throw new Error('filter not found: ' + slug);
const { data: links, error: lErr } = await supabase.from('air_purifier_retailer_links').select('*').eq('air_purifier_filter_id', filter.id).eq('status', 'approved');
if (lErr) throw lErr;
const outDir = path.join(process.cwd(), 'data/air-purifier/batch-production/audits/backups');
mkdirSync(outDir, { recursive: true });
const stamp = new Date().toISOString().replace(/[:.]/g, '-');
const outPath = path.join(outDir, 'ap-holmes-hapf30-amazon-demotion-pre-apply-' + stamp + '.json');
const payload = {
  contract: 'ap_holmes_hapf30_amazon_demotion_pre_apply_backup_v1',
  exported_at: new Date().toISOString(),
  git_head_hint: 'add5beb',
  filter_slug: slug,
  air_purifier_filter: filter,
  air_purifier_retailer_links: links ?? []
};
writeFileSync(outPath, JSON.stringify(payload, null, 2));
console.log(JSON.stringify({ ok: true, outPath, link_count: (links ?? []).length }, null, 2));
"

validation_commands_after_apply:
node --import tsx -e "
import { getSupabaseServerClient } from './src/lib/supabase/server-client.ts';
import { filterRealBuyRetailerLinks } from './src/lib/retailers/launch-buy-links.ts';
const supabase = getSupabaseServerClient();
const { data: filter } = await supabase.from('air_purifier_filters').select('id, slug').ilike('slug', 'holmes-hapf30').maybeSingle();
if (!filter) throw new Error('missing filter');
const { data: links } = await supabase.from('air_purifier_retailer_links').select('id, retailer_key, affiliate_url, browser_truth_classification, browser_truth_buyable_subtype, is_primary, status').eq('air_purifier_filter_id', filter.id).eq('status', 'approved');
const safe = filterRealBuyRetailerLinks(links ?? []);
console.log(JSON.stringify({ slug: filter.slug, approved_count: (links ?? []).length, gated_safe_count: safe.length, amazon_direct_buyable_remaining: (links ?? []).filter(r => r.retailer_key === 'amazon' && r.browser_truth_classification === 'direct_buyable').length }, null, 2));
if (safe.length !== 0) process.exit(1);
"
